arguments.command:
python -m pytest -q -o addopts='' && python - <<'PY'
import doctest
import semver

for version in (semver.VersionInfo(1), semver.VersionInfo.parse('1.2.3-rc.1+build.2')):
    parts = version.to_tuple()
    expected = dict(zip(('major', 'minor', 'patch', 'prerelease', 'build'), parts))
    assert isinstance(version.to_dict(), dict)
    assert version.to_dict() == expected
    result = version.to_dict()
    result['major'] = 99
    assert version.major == 1
    for i in range(-5, 5):
        assert version[i] == parts[i]
    for start in (None, -8, -3, 0, 2, 8):
        for stop in (None, -8, -1, 0, 3, 8):
            for step in (None, -2, -1, 1, 2):
                index = slice(start, stop, step)
                assert version[index] == parts[index]
    for index, error in ((5, IndexError), (-6, IndexError), ('major', TypeError), (1.0, TypeError), (slice(None, None, 0), ValueError)):
        try:
            version[index]
        except error:
            pass
        else:
            raise AssertionError('Expected %s for %r' % (error, index))
results = doctest.testmod(semver, extraglobs={'semver': semver})
assert results.failed == 0, results
print('Focused accessor/indexing checks and %d doctest examples passed.' % results.attempted)
PY
